const test=require('node:test'),assert=require('node:assert/strict');
global.RedaFigures={svg:()=>'<svg>fallback</svg>',animate(){},stills(){}};
require('../../reda-2/motion-specs.js');require('../../reda-2/reference-motion.js');require('../../reda-2/motion-v4.js');
const M=RedaMotionV4,dist=(a,b)=>Math.hypot(a[0]-b[0],a[1]-b[1]);
test('all fourteen movements retain fixed anatomical segment lengths and finite artwork',()=>{assert.equal(M.keys.length,14);for(const key of M.keys)for(let i=0;i<=100;i++){const p=M.pose(key,i/100);for(const [a,b,len] of [[p.hip,p.knee,72],[p.knee,p.ankle,72],[p.shoulder,p.hip,80],[p.shoulder,p.elbow,38],[p.elbow,p.hand,38]])assert.ok(Math.abs(dist(a,b)-len)<.001,key+' '+i);assert.doesNotMatch(M.svg(key,i/100),/NaN|Infinity/);}});
test('support release is continuous and advanced contact points do not slide',()=>{let old;for(let i=0;i<=1000;i++){const p=M.pose('sit-to-stand.support',i/1000);if(old)assert.ok(dist(p.hand,old)<1,'hand cannot jump at release');old=p.hand;const b=M.pose('split-squat.rfess-loaded',i/1000);assert.deepEqual(b.ankle,[345,364]);assert.deepEqual(b.back.ankle,[208,306]);const l=M.pose('leg-press.bilateral',i/1000);assert.deepEqual(l.hip,[230,290]);}});
test('mirroring stays inside the same camera; gradient IDs do not collide between cards',()=>{const a=M.svg('bridge.pause',1,'right'),b=M.svg('bridge.pause',1,'right');assert.match(a,/translate\(571 0\) scale\(-1 1\)/);assert.notEqual(a.match(/data-paint="([^"]+)/)[1],b.match(/data-paint="([^"]+)/)[1]);assert.equal(M.svg('bridge.single'),'<svg>fallback</svg>');});
